SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRANSACTION;
BEGIN TRY
    DECLARE @Now DATETIME2 = GETDATE();
    DECLARE @NowShamsi NVARCHAR(30) = CONVERT(NVARCHAR(30), @Now, 120);
    DECLARE @SeedUser NVARCHAR(150) = N'seed-inv-partcardex';

    DECLARE @Name NVARCHAR(200) = N'Inv_PartCardex_Report';
    DECLARE @Title NVARCHAR(200) = N'کاردکس کالا';
    DECLARE @EntityFullName NVARCHAR(300) = N'entities.app.inv.partcardex';

    DECLARE @CustomQuery NVARCHAR(MAX) = N'DECLARE @PartPk bigint = TRY_CAST(NULLIF(LTRIM(RTRIM(CONVERT(nvarchar(30), @PartId))), N'''') AS bigint);
DECLARE @HamkaranPartId bigint = (SELECT TOP (1) p.HamkaranId FROM Inv.Part AS p WHERE p.Id = @PartPk);
;WITH StoreRemaining AS (
    SELECT c.StoreRef, SUM(c.XValue) AS Remaining
    FROM ERPS.Erps.LGS3.vwCardexPart AS c
    WHERE @HamkaranPartId IS NOT NULL
      AND c.PartRef = @HamkaranPartId
      AND c.[State] <> 3
      AND c.TypeOfEffectOnStock = 1
    GROUP BY c.StoreRef
),
CardexRows AS (
    SELECT
        CAST(h.StockName AS nvarchar(512)) COLLATE DATABASE_DEFAULT AS StockName,
        CAST(h.VchNum AS bigint) AS VchNum,
        CAST(h.VchTypeTitle AS nvarchar(256)) COLLATE DATABASE_DEFAULT AS VchTypeTitle,
        CAST(h.VchDateShamsiDate AS nvarchar(10)) COLLATE DATABASE_DEFAULT AS Vchdate,
        CAST(h.Qty AS float) AS Qty,
        CAST(h.RemainingCount AS float) AS RemainingCount,
        CAST(h.Comment AS nvarchar(max)) COLLATE DATABASE_DEFAULT AS Comment
    FROM Inv.PartCardexHistory AS h
    WHERE @PartPk IS NOT NULL AND h.PartId = @PartPk

    UNION

    SELECT
        CAST(s.[Name] AS nvarchar(512)) COLLATE DATABASE_DEFAULT,
        CAST(hd.Number AS bigint),
        CAST(ivf.[Name] AS nvarchar(256)) COLLATE DATABASE_DEFAULT,
        CAST(dd.SolarDate AS nvarchar(10)) COLLATE DATABASE_DEFAULT,
        CAST(i.Quantity AS float),
        CAST(sr.Remaining AS float),
        CAST(i.[Description] AS nvarchar(max)) COLLATE DATABASE_DEFAULT
    FROM ERPS.Erps.LGS3.InventoryVoucherItem AS i
    JOIN ERPS.Erps.LGS3.InventoryVoucher AS hd ON i.InventoryVoucherRef = hd.InventoryVoucherID
    JOIN ERPS.Erps.LGS3.Part AS p ON p.PartID = i.PartRef
    JOIN ERPS.Erps.LGS3.InventoryVoucherSpecification AS ivf ON hd.InventoryVoucherSpecificationRef = ivf.InventoryVoucherSpecificationID
    JOIN ERPS.Erps.LGS3.Store AS s ON s.StoreID = hd.StoreRef
    JOIN ERPS.Erps.USR3.Gnr_DimDate AS dd ON dd.[Date] = hd.[Date]
    LEFT JOIN StoreRemaining AS sr ON sr.StoreRef = i.StoreRef
    WHERE @HamkaranPartId IS NOT NULL AND p.PartID = @HamkaranPartId
)
--!--mainsection
SELECT
