    r.StockName AS [t1_StockName],
    r.VchNum AS [t1_VchNum],
    r.VchTypeTitle AS [t1_VchTypeTitle],
    r.Vchdate AS [t1_Vchdate],
    r.Qty AS [t1_Qty],
    r.RemainingCount AS [t1_RemainingCount],
    r.Comment AS [t1_Comment]
FROM CardexRows AS r';

